      D.className = "customer-lang-button";
      D.type = "button";
      D.setAttribute("aria-label", "客户语言设置");
      D.setAttribute("title", "客户语言设置");
      D.style.cssText =
        "background:none;border:none;padding:8px;margin:0;cursor:pointer;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;transition:background-color 0.2s;vertical-align:middle;width:40px;height:40px;flex-shrink:0;color:" +
        col +
        ";";
      D.innerHTML = CUSTOMER_LANG_SVG;
