      // 先展示缓存/本地；官方改名时新标题可能尚未入缓存，先保留旧备注防闪空
      var next = getRemark(key);
      if (!String(next || "").trim() && preferNative !== false && String(prevNote || "").trim()) {
        next = prevNote;
      }
      if (!String(next || "").trim()) next = getLocalRemark(key);
